// Model recognition — paraphrased contexts from the exam map (§16)

export type Scenario = {
  id: string; title: string; ref: string; topic: string; node: string;
  text: string; triggers: string[];
  qs: { label: string; options: Choice[] }[];
  model: Choice[];
  explain: string;
  practice?: string;
};

const Q = (label: string, right: string, wrong: string[], why: string) => ({
  label,
  options: [{ text: right, correct: true, feedback: why }, ...wrong.map((w) => ({ text: w, feedback: `Non — ${why}` }))],
});
const WHO_MKT = 'Les acheteurs et vendeurs d’un marché concurrentiel';

